export const SHOWCASE_COVERAGE_TARGETS = Object.freeze(RAW_SHOWCASE_TARGETS.map((item) => Object.freeze(item)));
export const SHOWCASE_ASSIGNMENTS = Object.freeze(RAW_SHOWCASE_ASSIGNMENTS.map((item) => Object.freeze(item)));

export function getShowcaseAssignments({ sport = "", league = "", activeOnly = true, season = 2026 } = {}) {
  return SHOWCASE_ASSIGNMENTS.filter((item) => (!sport || item.sport === sport) && (!league || item.league === league)
    && (!activeOnly || item.active) && item.seasonFrom <= season && (!item.seasonTo || item.seasonTo >= season));
}

export function getIllustrationPriorityQueue({ season = 2026 } = {}) {
  const exactIds = new Set(ILLUSTRATION_REGISTRY.filter((item) => ["athlete", "fighter", "driver"].includes(item.entityType)).map((item) => item.canonicalEntityId));
  const queue = getShowcaseAssignments({ season }).map((item) => Object.freeze({
    ...item, illustrated: exactIds.has(item.canonicalEntityId),
    queuePriority: (item.displayPriority || 0) + (item.showcaseRole === "team_representative" ? 10 : 0),
  })).sort((left, right) => Number(left.illustrated) - Number(right.illustrated)
    || right.queuePriority - left.queuePriority || left.canonicalEntityId.localeCompare(right.canonicalEntityId));
  return Object.freeze(queue);
}
